const vehicleFields=v=>[field('registrationNumber','Registration number','text',{value:v?.registrationNumber,maxLength:30}),field('make','Make','text',{value:v?.make,maxLength:100}),field('model','Model','text',{value:v?.model,maxLength:100}),field('year','Year','number',{value:v?.year,min:1900,max:2100,step:'1'}),field('vin','VIN','text',{optional:true,value:v?.vin,maxLength:50}),field('color','Colour','text',{optional:true,value:v?.color,maxLength:50})];
async function vehicles(host){const data=await list('/api/vehicles');actions(host,[['Add vehicle',()=>modal('Add vehicle',h=>form(h,null,vehicleFields(),d=>request('/api/vehicles','POST',{...d,customerId:auth.customerId}),'Add vehicle')),true]]);const grid=E('div','wf-grid three');host.append(grid);if(!data.length)empty(host,'No vehicles registered.','Add your first vehicle to book a service.');for(const v of data){const c=card(grid,v.make+' '+v.model,'My vehicle');c.append(E('p','',v.year+' · '+v.registrationNumber));info(c,{'Registration':v.registrationNumber,'VIN':v.vin,'Colour':v.color});actions(c,[['Edit',()=>modal('Edit vehicle',h=>form(h,null,vehicleFields(v),d=>request('/api/vehicles/'+v.id,'PUT',{...d,customerId:auth.customerId})))],['Delete',async()=>{if(confirm('Delete '+v.registrationNumber+'?'))await save('/api/vehicles/'+v.id,'DELETE');}]]);}}
