async function profile(host){const c=await request('/api/customers/'+auth.customerId);form(host,'Profile settings',[field('firstName','First name','text',{value:c.firstName,maxLength:100}),field('lastName','Last name','text',{value:c.lastName,maxLength:100}),field('email','Email address','email',{value:c.email,maxLength:191}),field('phone','Mobile number','tel',{value:c.phone,maxLength:30}),field('address','Address','textarea',{optional:true,value:c.address,maxLength:500})],async d=>{await request('/api/customers/'+auth.customerId,'PUT',{...d,address:d.address||''});auth={...api.auth(),fullName:d.firstName+' '+d.lastName,email:d.email,phone:d.phone};api.save(auth);identity();},'Save changes');}
