async function reports(host){const render=async(from,to)=>{const target=host.querySelector('.wf-report-result');target.replaceChildren();const qs=new URLSearchParams();if(from)qs.set('from',new Date(from).toISOString());if(to)qs.set('to',new Date(to+'T23:59:59').toISOString());const d=await request('/api/reports/operational-summary?'+qs);stats(target,[['Total jobs',d.workOrders.total],['Completed jobs',d.workOrders.completed],['Invoiced',money(d.billing.invoicedAmount)],['Outstanding',money(d.billing.outstandingAmount)]]);const c=card(target,'Operational summary');info(c,{'Period start':when(d.from),'Period end':when(d.to),'Cancelled jobs':d.workOrders.cancelled,'Invoices':d.billing.invoices,'Paid':money(d.billing.paidAmount),'Low stock items':d.inventory.lowStockItems,'Pending requisitions':d.inventory.pendingRequisitions,'Open vendor requests':d.procurement.openQuoteRequests,'Open purchase orders':d.procurement.openPurchaseOrders});};form(host,'Report date range',[field('from','From','date',{optional:true}),field('to','To','date',{optional:true})],async d=>{if(d.from&&d.to&&d.from>d.to)throw new Error('The end date must follow the start date.');await render(d.from,d.to);},'Run report',{keep:true});host.append(E('div','wf-report-result'));await render();host.append(button('Print report',()=>window.print()));}
