function identity(){const initials=(auth.fullName||'Account').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();document.querySelectorAll('[data-wf-name]').forEach(x=>x.textContent=auth.fullName||'Account');document.querySelectorAll('[data-wf-email]').forEach(x=>x.textContent=auth.email||'');document.querySelectorAll('[data-wf-avatar]').forEach(x=>x.textContent=initials);}
async function open(id,selectedId){const m=modules[role].find(x=>x[0]===id)||modules[role][0];active=m[0];document.body.dataset.wfModule=active;document.body.dataset.wfRole=role;const ticket=++epoch;clearInterval(timerInterval);closeDialog();document.querySelector('.wf-sidebar')?.classList.remove('open');document.querySelectorAll('.wf-nav button').forEach(b=>b.classList.toggle('active',b.dataset.module===active));document.querySelector('#wf-title').textContent=m[1];const hash='#'+active;if(location.hash!==hash)historyReplace(hash);root.replaceChildren(E('div','wf-loading','Loading your records…'));const stage=E('div');stage._ticket=ticket;const head=E('div','wf-page-head'),title=E('div');title.append(E('span','wf-label',role==='ServiceAdvisor'?'Service advisor':role),E('h2','',m[1]),E('p','',hints[active]||''));head.append(title,button('Refresh',()=>open(active)));stage.append(head);try{await m[2](stage,selectedId);if(ticket===epoch){root.replaceChildren(stage);if(toastText){notice(stage,toastText);toastText=null;}}}catch(e){if(ticket===epoch){root.replaceChildren(stage);notice(stage,e.message,true);stage.append(button('Retry',()=>open(active)));}}}
